 if(/hint|stuck|help|clue|don.?t get|confus/.test(t)){const it=currentItem();if(it&&it.hint)return voice(it.hint,'hint');return voice((L.explain.kid||[L.keyIdea])[ctx.hintStep++%L.explain.kid.length],'hint')}
